local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Public announcements are separate from the private party synchronization protocol.
local L = LibStub("AceLocale-3.0"):GetLocale("APR")
APR.announcements = { quests = {}, routes = {} }
local announcements = APR.announcements
local formats = {
    ANNOUNCE_LEVEL = L["ANNOUNCE_LEVEL"], ANNOUNCE_LEVEL_EMOTE = L["ANNOUNCE_LEVEL_EMOTE"],
    ANNOUNCE_QUEST = L["ANNOUNCE_QUEST"], ANNOUNCE_OBJECTIVE = L["ANNOUNCE_OBJECTIVE"],
    ANNOUNCE_COLLECT = L["ANNOUNCE_COLLECT"], ANNOUNCE_FLIGHT = L["ANNOUNCE_FLIGHT"],
    ANNOUNCE_HEARTHSTONE = L["ANNOUNCE_HEARTHSTONE"], ANNOUNCE_ROUTE = L["ANNOUNCE_ROUTE"],
    ANNOUNCE_ROUTE_EMOTE = L["ANNOUNCE_ROUTE_EMOTE"],
}

function announcements:Send(kind, key, soloKey, ...)
    local profile = APR.settings and APR.settings.profile
    local options = profile and profile.announcements
    if not profile or not profile.enableAddon or not options or not options.enabled or not options[kind] then return end
    if APR.routeValidationPending or APR.routeValidationFailed or APR.startupQuestStatePending then return end
    local api = C_ChatInfo
    if api and api.InChatMessagingLockdown and api.InChatMessagingLockdown() then return end
    local channel
    if IsInGroup() then
        if not options.group then return end
        channel = LE_PARTY_CATEGORY_INSTANCE and IsInGroup(LE_PARTY_CATEGORY_INSTANCE) and "INSTANCE_CHAT"
            or (IsInRaid() and "RAID" or "PARTY")
    elseif soloKey and options.solo then
        channel, key = "EMOTE", soloKey
    else
        return
    end
    -- Forever requires hardware input for addon EMOTEs outside instances.
    -- Gameplay events cannot provide it, and pcall cannot suppress ADDON_ACTION_BLOCKED.
    if channel == "EMOTE" and APR:GetGameVersion() == APR.GAME_VERSIONS.Forever
        and not (IsInInstance and IsInInstance()) then return end
    for index = 1, select("#", ...) do
        if APRSecret and not APRSecret:CanAccessValue(select(index, ...)) then return end
    end
    local message = string.format(formats[key], ...)
    message = channel == "EMOTE" and (message .. " [APR]") or ("[APR] " .. message)
    -- Remove embedded links/textures/colors and control characters; native chat has a byte limit.
    message = message:gsub("|H.-|h(.-)|h", "%1"):gsub("|T.-|t", ""):gsub("|A.-|a", "")
        :gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):gsub("[%c|]", "")
    if #message > 255 then
        local suffix = channel == "EMOTE" and " [APR]" or ""
        if suffix ~= "" then message = message:sub(1, -#suffix - 1) end
        local boundary = 253 - #suffix
        while boundary > 0 and message:byte(boundary) >= 128 and message:byte(boundary) < 192 do
            boundary = boundary - 1
        end
        message = message:sub(1, boundary - 1) .. "..." .. suffix
    end
    local send = api and api.SendChatMessage or SendChatMessage
    if send then return --[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](send, message, channel) end
end--[[APR_DIAG]]; announcements.Send = APRTrace("APR-Core/features/player/Announcements.lua:11:announcements:Send#1", announcements.Send)--[[/APR_DIAG]]

-- Called only after a complete native quest-cache refresh. Initial observations are silent.
function announcements:ObserveQuests()
    local profile = APR.settings and APR.settings.profile
    if not profile or not profile.enableAddon or not profile.announcements or not profile.announcements.enabled then
        self.quests = {}
        return
    end
    local previous = self.profile == profile and self.quests or {}
    self.profile = profile
    self.quests = {}
    for id, quest in pairs(APR.ActiveQuests or {}) do
        local complete = quest.status == APR.QUEST_STATUS.COMPLETE
        local now = { complete = complete, objectives = {} }
        self.quests[id] = now
        local old = previous[id]
        local questAnnounced
        if old and not old.complete and complete then
            questAnnounced = self:Send("quest", "ANNOUNCE_QUEST", nil, quest.title)
        end
        for index, objective in ipairs(quest.objectives or {}) do
            local finished = objective.status == APR.QUEST_STATUS.COMPLETE
            now.objectives[index] = { finished = finished, type = objective.type }
            local before = old and old.objectives[index]
            if not questAnnounced and (not complete or (old and not old.complete))
                and before and not before.finished and finished and before.type == objective.type then
                if objective.type == "item" then
                    self:Send("collect", "ANNOUNCE_COLLECT", nil, objective.text)
                else
                    self:Send("objective", "ANNOUNCE_OBJECTIVE", nil, objective.text, quest.title)
                end
            end
        end
    end
end--[[APR_DIAG]]; announcements.ObserveQuests = APRTrace("APR-Core/features/player/Announcements.lua:48:announcements:ObserveQuests#2", announcements.ObserveQuests)--[[/APR_DIAG]]

function announcements:RouteCompleted(route)
    if not route or self.routes[route] then return end
    self.routes[route] = true
    local history = APR.transitionHistory
    local last = history and history.entries[history.cursor]
    if APR.manualSkipRefreshing or not last or last.route ~= route or last.reason ~= "automatic" then return end
    local label = APR:GetRouteDisplayName(route)
    if label then self:Send("route", "ANNOUNCE_ROUTE", "ANNOUNCE_ROUTE_EMOTE", label) end
end--[[APR_DIAG]]; announcements.RouteCompleted = APRTrace("APR-Core/features/player/Announcements.lua:76:announcements:RouteCompleted#3", announcements.RouteCompleted)--[[/APR_DIAG]]

